<?php
namespace App\Http\Controllers\Management;use App\Http\Controllers\Controller;use App\Models\BackupRun;use App\Services\Management\BackupService;use Illuminate\Http\Request;
class BackupController extends Controller{public function index(Request $r){abort_unless($r->user()->isManager(),403);$q=BackupRun::query();if($r->user()->role!=='super_admin')$q->where('property_id',$r->user()->property_id);return view('management.backups',['runs'=>$q->latest()->limit(100)->get()]);}public function store(Request $r,BackupService $s){abort_unless($r->user()->isManager(),403);$d=$r->validate(['type'=>'required|in:database,files,full']);$s->request($r->user()->property_id,$r->user()->id,$d['type']);return back()->with('success','Backup request queued. Configure a production backup worker/storage target before relying on this record.');}}
